H.background();
H.text("Solubility rules: soluble (aq) vs precipitate (s)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Slide to pick a cation-anion pair; rules decide if a solid drops out", 24, 52, { color: H.colors.sub, size: 13 });
const pairs = [
  { f: "NaCl",   sol: true,  why: "Group 1 salts always soluble" },
  { f: "KNO3",   sol: true,  why: "all nitrates soluble" },
  { f: "AgCl",   sol: false, why: "Ag+ halides insoluble" },
  { f: "BaSO4",  sol: false, why: "Ba2+ sulfate insoluble" },
  { f: "PbI2",   sol: false, why: "Pb2+ halides insoluble" },
  { f: "CuS",    sol: false, why: "most sulfides insoluble" },
  { f: "CaCl2",  sol: true,  why: "most chlorides soluble" },
  { f: "NH4Cl",  sol: true,  why: "ammonium salts soluble" }
];
const n = pairs.length;
let idx = Math.round(P.pair);
if (!(idx >= 0)) idx = 0;
if (idx > n - 1) idx = n - 1;
const cur = pairs[idx];
const cx = H.W / 2;
const bx = cx - 120, by = 110, bw = 240, bh = 300;
H.rect(bx, by, bw, bh, { stroke: H.colors.grid, width: 3, radius: 8 });
H.line(bx, by + 70, bx + bw, by + 70, { color: H.colors.accent, width: 1, dash: [5,5] });
H.text("solution", bx + bw - 8, by + 60, { color: H.colors.sub, size: 11, align: "right" });
if (cur.sol) {
  for (let i = 0; i < 14; i++) {
    const ph = i * 0.9;
    const x = bx + 30 + ((i * 53) % (bw - 60)) + 14 * Math.sin(t * 1.2 + ph);
    const y = by + 95 + ((i * 71) % (bh - 130)) + 12 * Math.cos(t * 1.1 + ph);
    const pos = i % 2 === 0;
    H.circle(x, y, 7, { fill: pos ? H.colors.accent2 : H.colors.good });
  }
  H.text(cur.f + " (aq)", cx, by + bh + 34, { color: H.colors.good, size: 22, weight: 700, align: "center" });
  H.text("dissolves -> free ions", cx, by + bh + 60, { color: H.colors.sub, size: 13, align: "center" });
} else {
  const settle = Math.min(1, (t % 4) / 2.2);
  for (let i = 0; i < 24; i++) {
    const col = i % 6;
    const row = Math.floor(i / 6);
    const x = bx + 40 + col * 30 + (1 - settle) * 6 * Math.sin(t * 3 + i);
    const yTarget = by + bh - 16 - row * 16;
    const yFall = by + 100 + (yTarget - (by + 100)) * settle;
    H.circle(x, yFall, 8, { fill: H.colors.warn, stroke: H.colors.ink, width: 1 });
  }
  H.text(cur.f + " (s)", cx, by + bh + 34, { color: H.colors.warn, size: 22, weight: 700, align: "center" });
  H.text("precipitate settles out", cx, by + bh + 60, { color: H.colors.sub, size: 13, align: "center" });
}
H.text("Rule:  " + cur.why, 24, 506, { color: H.colors.ink, size: 14, weight: 700 });
H.text("pair " + (idx + 1) + " of " + n + ":  " + cur.f + "  ->  " + (cur.sol ? "SOLUBLE (aq)" : "INSOLUBLE (s)"), 24, 530, { color: cur.sol ? H.colors.good : H.colors.warn, size: 13 });
